import std.convert.Parsable

class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        let maxLen = max(num1.length, num2.length)
        var n1 = num1
        var n2 = num2
        while n1.length < maxLen {
            n1 = "0" + n1
        }
        while n2.length < maxLen {
            n2 = "0" + n2
        }

        var carry = 0
        var result = ""
        for i in countdown(maxLen - 1, 0, -1) {
            let d1 = n1[i].toInt()
            let d2 = n2[i].toInt()
            let total = d1 + d2 + carry
            carry = total / 10
            let digit = total % 10
            result = digit.toString() + result
        }
        if carry > 0 {
            result = carry.toString() + result
        }
        return result
    }

    public static func subtract(num1: String, num2: String): String {
        var negative = false
        var n1 = num1
        var n2 = num2

        if n1.length < n2.length {
            (n1, n2) = (n2, n1)
            negative = true
        } else if n1.length == n2.length {
            if n1 < n2 {
                (n1, n2) = (n2, n1)
                negative = true
            }
        }

        let maxLen = max(n1.length, n2.length)
        while n1.length < maxLen {
            n1 = "0" + n1
        }
        while n2.length < maxLen {
            n2 = "0" + n2
        }

        var borrow = 0
        var result = ""
        for i in countdown(maxLen - 1, 0, -1) {
            var diff = n1[i].toInt() - n2[i].toInt() - borrow
            if diff < 0 {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            result = diff.toString() + result
        }

        // Remove leading zeros
        while result.length > 1 && result[0] == '0' {
            result = result[1:]
        }

        if negative {
            result = "-" + result
        }
        return result
    }

    public static func multiply(num1: String, num2: String): String {
        let len1 = num1.length
        let len2 = num2.length
        var result = [Int](repeating: 0, count: len1 + len2)

        for i in countdown(len1 - 1, 0, -1) {
            for j in countdown(len2 - 1, 0, -1) {
                let mul = num1[i].toInt() * num2[j].toInt()
                let p1 = i + j
                let p2 = i + j + 1
                let total = mul + result[p2]

                result[p1] += total / 10
                result[p2] = total % 10
            }
        }

        var start = 0
        while start < result.count - 1 && result[start] == 0 {
            start += 1
        }

        var resStr = ""
        for i in start..<result.count {
            resStr += result[i].toString()
        }

        return resStr
    }
}

