import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = ""
        for (char in this.binary_string) {
            if (char == '0' || char == '1') {
                cleaned = cleaned + char.toString()
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        var zeroes_count: Int64 = 0
        var ones_count: Int64 = 0
        for (char in this.binary_string) {
            if (char == '0') {
                zeroes_count = zeroes_count + 1
            } else if (char == '1') {
                ones_count = ones_count + 1
            }
        }
        var total_length = this.binary_string.size
        var result = HashMap<String, Float64>()
        result.put("Zeroes", (zeroes_count as Float64) / (total_length as Float64))
        result.put("Ones", (ones_count as Float64) / (total_length as Float64))
        result.put("Bit length", total_length as Float64)
        return result
    }

    public func convert_to_ascii(): String {
        var byte_array: Array<UInt8> = []
        var i: Int64 = 0
        while (i < this.binary_string.size) {
            var byte_str = this.binary_string.substring(i, i + 8)
            var decimal = UInt8.parse(byte_str, 2)
            byte_array.push(decimal)
            i = i + 8
        }
        return String.fromUtf8(byte_array)
    }

    public func convert_to_utf8(): String {
        var byte_array: Array<UInt8> = []
        var i: Int64 = 0
        while (i < this.binary_string.size) {
            var byte_str = this.binary_string.substring(i, i + 8)
            var decimal = UInt8.parse(byte_str, 2)
            byte_array.push(decimal)
            i = i + 8
        }
        return String.fromUtf8(byte_array)
    }
}

