import std.collection.HashMap

class CamelCaseMap {
    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        let convertedKey = _convert_key(key)
        return _data[convertedKey as String]
    }

    public func __setitem__(key: String, value: Any): Unit {
        let convertedKey = _convert_key(key)
        _data[convertedKey as String] = value
    }

    public func __delitem__(key: String): Unit {
        let convertedKey = _convert_key(key)
        _data.remove(convertedKey as String)
    }

    public func __len__(): Int64 {
        return _data.size
    }

    public func _convert_key(key: Any): Any {
        match (key) {
            case is String => _to_camel_case(key as String)
            case _ => key
        }
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split('_')
        if (parts.size() == 0) {
            return ""
        }
        var result = parts[0]
        for (var i = 1; i < parts.size(); i = i + 1) {
            let part = parts[i]
            if (part.length() > 0) {
                result = result + part[0].toUpper() + part.substring(1)
            }
        }
        return result
    }
}

