import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        for (var i = 0; i < this.students.size(); i = i + 1) {
            if (this.students.at(i).get("name") == student.get("name")) {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if (this.students_registration_classes.containsKey(student_name)) {
            this.students_registration_classes.get(student_name).add(class_name)
        } else {
            var class_list = ArrayList<String>()
            class_list.add(class_name)
            this.students_registration_classes.put(student_name, class_list)
        }
        return this.students_registration_classes.get(student_name)
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        var student_list = ArrayList<String>()
        for (var i = 0; i < this.students.size(); i = i + 1) {
            var student = this.students.at(i)
            if (student.get("major") == major) {
                student_list.add(student.get("name"))
            }
        }
        return student_list
    }

    public func get_all_major(): ArrayList<String> {
        var major_list = ArrayList<String>()
        for (var i = 0; i < this.students.size(); i = i + 1) {
            var student = this.students.at(i)
            var major = student.get("major")
            if (!major_list.contains(major)) {
                major_list.add(major)
            }
        }
        return major_list
    }

    public func get_most_popular_class_in_major(major: String): String {
        var class_list = ArrayList<String>()
        for (var i = 0; i < this.students.size(); i = i + 1) {
            var student = this.students.at(i)
            if (student.get("major") == major) {
                var student_name = student.get("name")
                if (this.students_registration_classes.containsKey(student_name)) {
                    var registered_classes = this.students_registration_classes.get(student_name)
                    for (var j = 0; j < registered_classes.size(); j = j + 1) {
                        class_list.add(registered_classes.at(j))
                    }
                }
            }
        }

        if (class_list.size() == 0) {
            return ""
        }

        var class_count = HashMap<String, Int64>()
        for (var i = 0; i < class_list.size(); i = i + 1) {
            var cls = class_list.at(i)
            if (class_count.containsKey(cls)) {
                class_count.put(cls, class_count.get(cls) + 1)
            } else {
                class_count.put(cls, 1)
            }
        }

        var max_count = 0
        var most_popular_class = ""
        for (var i = 0; i < class_list.size(); i = i + 1) {
            var cls = class_list.at(i)
            if (class_count.get(cls) > max_count) {
                max_count = class_count.get(cls)
                most_popular_class = cls
            }
        }

        return most_popular_class
    }
}

