import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File(file_name)
        let input = FileInputStream(file)
        let buffer = Array<Byte>(1024, repeat: 0)
        var content = ""
        var bytesRead = input.read(buffer)
        while (bytesRead > 0) {
            let str = String.fromBytes(buffer.slice(0, bytesRead))
            content = content + str
            bytesRead = input.read(buffer)
        }
        input.close()

        let lines = content.split("\n")
        if (lines.size() == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title = lines[0].split(",")
        let data = ArrayList<ArrayList<String>>()

        for (i in 1 ..< lines.size()) {
            if (lines[i].isEmpty()) {
                continue
            }
            let row = lines[i].split(",")
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File(file_name)
        let output = FileOutputStream(file)
        var content = ""

        for (row in data) {
            var line = ""
            for (i in 0 ..< row.size()) {
                if (i > 0) {
                    line = line + ","
                }
                line = line + row[i]
            }
            content = content + line + "\n"
        }

        let bytes = content.toBytes()
        output.write(bytes)
        output.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)
        let newFileName = save_file_name.split(".")[0] + "_process.csv"
        let newData = ArrayList<ArrayList<String>>()
        newData.add(title)

        let colData = ArrayList<String>()
        for (row in data) {
            if (N >= 0 && N < row.size()) {
                colData.add(row[N].toUpper())
            }
        }
        newData.add(colData)

        return this.write_csv(newData, newFileName)
    }
}

