import std.math.sqrt
import std.math.abs

class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for (let value in this.data) {
            sum += value
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        let size = this.data.size()
        if (size == 0) {
            return 0.0
        }
        var min = this.data[0]
        for (let value in this.data) {
            if (value < min) {
                min = value
            }
        }
        return min
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        let size = this.data.size()
        if (size == 0) {
            return 0.0
        }
        var max = this.data[0]
        for (let value in this.data) {
            if (value > max) {
                max = value
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let size = this.data.size()
        if (size == 0) {
            return 0.0
        }
        let mean = this.get_sum() / Float64(size)
        var sumSquaredDifferences: Float64 = 0.0
        for (let value in this.data) {
            let diff = value - mean
            sumSquaredDifferences += diff * diff
        }
        let variance = sumSquaredDifferences / Float64(size)
        return round(variance, 2)
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance = this.get_variance()
        return round(sqrt(variance), 2)
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let size = this.data.size()
        if (size <= 1) {
            return 0.0
        }

        let mean = this.get_sum() / Float64(size)

        var sumXY: Float64 = 0.0
        var sumX2: Float64 = 0.0
        var sumY2: Float64 = 0.0

        for (let i in 0..<size) {
            let x = this.data[i]
            let y = this.data[i]
            let dx = x - mean
            let dy = y - mean
            sumXY += dx * dy
            sumX2 += dx * dx
            sumY2 += dy * dy
        }

        if (sumX2 == 0.0 || sumY2 == 0.0) {
            return 0.0
        }

        return sumXY / sqrt(sumX2 * sumY2)
    }
}

