import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    /*
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    */

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.length
        if n != data2.length || n == 0 {
            return 0.0
        }

        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        for i in 0..<n {
            sum1 += data1[i]
            sum2 += data2[i]
        }
        let mean1 = sum1 / n.toFloat64()
        let mean2 = sum2 / n.toFloat64()

        var numerator: Float64 = 0.0
        var sum_sq1: Float64 = 0.0
        var sum_sq2: Float64 = 0.0

        for i in 0..<n {
            let diff1 = data1[i] - mean1
            let diff2 = data2[i] - mean2
            numerator += diff1 * diff2
            sum_sq1 += diff1 * diff1
            sum_sq2 += diff2 * diff2
        }

        let denominator = sqrt(sum_sq1) * sqrt(sum_sq2)
        if abs(denominator) < 1e-10 {
            return 0.0
        }
        return numerator / denominator
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.length
        if n == 0 {
            return 0.0
        }

        var sum: Float64 = 0.0
        for i in 0..<n {
            sum += data[i]
        }
        let mean = sum / n.toFloat64()

        var variance: Float64 = 0.0
        for i in 0..<n {
            let diff = data[i] - mean
            variance += diff * diff
        }
        variance = variance / n.toFloat64()
        let std_deviation = sqrt(variance)

        if abs(std_deviation) < 1e-10 {
            return 0.0
        }

        var skew: Float64 = 0.0
        for i in 0..<n {
            let diff = data[i] - mean
            skew += diff * diff * diff
        }

        skew = skew * n.toFloat64() / ((n - 1).toFloat64() * (n - 2).toFloat64() * std_deviation * std_deviation * std_deviation)
        return skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.length
        if n == 0 {
            return 0.0 / 0.0  // NaN
        }

        var sum: Float64 = 0.0
        for i in 0..<n {
            sum += data[i]
        }
        let mean = sum / n.toFloat64()

        var variance: Float64 = 0.0
        for i in 0..<n {
            let diff = data[i] - mean
            variance += diff * diff
        }
        variance = variance / n.toFloat64()
        let std_dev = sqrt(variance)

        if abs(std_dev) < 1e-10 {
            return 0.0 / 0.0  // NaN
        }

        var fourth_moment: Float64 = 0.0
        for i in 0..<n {
            let diff = data[i] - mean
            fourth_moment += diff * diff * diff * diff
        }
        fourth_moment = fourth_moment / n.toFloat64()

        return (fourth_moment / (std_dev * std_dev * std_dev * std_dev)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        if abs(sigma) < 1e-10 {
            for _ in 0..<data.length {
                result.append(0.0)
            }
            return result
        }

        let coefficient = 1.0 / (sigma * sqrt(2.0 * 3.14159265358979323846))
        for i in 0..<data.length {
            let x = data[i]
            let exponent = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            result.append(coefficient * exp(exponent))
        }
        return result
    }
}

