import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        var ciphertext = ""
        for (char in plaintext) {
            if (char.isAlpha()) {
                let asciiOffset = char.isUpper() ? 65 : 97
                let shiftedChar = ((char.toUInt8() - asciiOffset + shift) % 26 + asciiOffset).toChar()
                ciphertext += shiftedChar.toString()
            } else {
                ciphertext += char.toString()
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        var encrypted_text = ""
        var key_index = 0
        for (char in plain_text) {
            if (char.isAlpha()) {
                let shift = (this.key[key_index % this.key.length].toLower().toUInt8() - 'a'.toUInt8()) % 26
                let base = char.toLower().toUInt8() - 'a'.toUInt8()
                let encrypted_char_code = (base + shift) % 26 + 'a'.toUInt8()
                let encrypted_char = encrypted_char_code.toChar()
                encrypted_text += char.isUpper() ? encrypted_char.toUpper().toString() : encrypted_char.toString()
                key_index += 1
            } else {
                encrypted_text += char.toString()
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        if (rails <= 1 || plain_text.length <= rails) {
            return plain_text
        }

        let railArray = ArrayList<ArrayList<Char>>()
        for (i in 0..<rails) {
            railArray.add(ArrayList<Char>())
            for (_ in 0..<plain_text.length) {
                railArray[i].add('\n')
            }
        }

        var direction = -1
        var row = 0
        var col = 0

        for (char in plain_text) {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            railArray[row][col] = char
            col += 1
            row += direction
        }

        var encrypted_text = ""
        for (i in 0..<rails) {
            for (j in 0..<plain_text.length) {
                if (railArray[i][j] != '\n') {
                    encrypted_text += railArray[i][j].toString()
                }
            }
        }

        return encrypted_text
    }
}

