    let postfix_stack: ArrayDeque<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayDeque<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0

        */
        self.prepare(self.transform(expression))
        let result_stack = ArrayDeque<String>()
        self.postfix_stack.reverse()

        while (!self.postfix_stack.isEmpty()) {
            let current_op = self.postfix_stack.popFront().getOrThrow()
            if (!ExpressionCalculator.is_operator(current_op)) {
                let clean_op = current_op.replace("~", "-")
                result_stack.pushBack(clean_op)
            } else {
                let second_value = result_stack.popBack().getOrThrow()
                let first_value = result_stack.popBack().getOrThrow()

                let clean_first = first_value.replace("~", "-")
                let clean_second = second_value.replace("~", "-")

                let temp_result = ExpressionCalculator._calculate(Decimal(clean_first), Decimal(clean_second), current_op)
                result_stack.pushBack(temp_result.toString())
            }
        }
        return Float64(result_stack.popBack().getOrThrow())
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        let op_stack = ArrayDeque<String>()
        op_stack.pushBack(",")
        let arr = expression.toChars()
        var current_index = 0
        var count = 0

        for (i, current_op) in arr.enumerated() {
            let current_op_str = String(current_op)
            if (ExpressionCalculator.is_operator(current_op_str)) {
                if (count > 0) {
                    self.postfix_stack.pushBack(String(arr[current_index..<(current_index + count)]))
                }
                let peek_op = op_stack.back().getOrThrow()
                if (current_op_str == ")") {
                    while (op_stack.back().getOrThrow() != "(") {
                        self.postfix_stack.pushBack(op_stack.popBack().getOrThrow())
                    }
                    op_stack.popBack() // pop the "("
                } else {
                    while (current_op_str != "(" && op_stack.back().getOrThrow() != "," && self.compare(current_op_str, op_stack.back().getOrThrow())) {
                        self.postfix_stack.pushBack(op_stack.popBack().getOrThrow())
                    }
                    op_stack.pushBack(current_op_str)
                }

                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }

        if (count > 1 || (count == 1 && !ExpressionCalculator.is_operator(String(arr[current_index])))) {
            self.postfix_stack.pushBack(String(arr[current_index..<(current_index + count)]))
        }

        while (op_stack.back().getOrThrow() != ",") {
            self.postfix_stack.pushBack(op_stack.popBack().getOrThrow())
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        >>> ExpressionCalculator.is_operator("+")
        true

        */
        return c in {"+", "-", "*", "/", "(", ")", "%"}
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        true

        */
        let cur_op = if (cur == "%") { "/" } else { cur }
        let peek_op = if (peek == "%") { "/" } else { peek }
        return operat_priority[Int64(peek_op.toChars()[0]) - 40] >= operat_priority[Int64(cur_op.toChars()[0]) - 40]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        >>> ExpressionCalculator._calculate("2", "3", "+")
        5.0

        */
        switch (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => return first_value / second_value
            case "%" => return first_value % second_value
            default => panic("Unexpected operator: ${current_op}")
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        >>> ExpressionCalculator.transform("2 + 3 * 4")
        "2+3*4"

        */
        var expr = expression
        expr = Regex("\\s+").replaceAll(expr, "")
        expr = Regex("=$").replaceAll(expr, "")
        let arr = expr.toChars()

        for (i, c) in arr.enumerated() {
            if (c == '-' && (i == 0 || arr[i - 1] in {'+', '-', '*', '/', '(', 'E', 'e'})) {
                arr[i] = '~'
            }
        }

        if (arr[0] == '~' && arr.size > 1 && arr[1] == '(') {
            arr[0] = '-'
            return "0" + String(arr)
        } else {
            return String(arr)
        }
    }
}
