import std.net.*
import std.posix.gethostname

class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        return IPAddress.tryParse(ip_address) != None && IPAddress.parse(ip_address).isIPv4()
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        return IPAddress.tryParse(ip_address) != None && IPAddress.parse(ip_address).isIPv6()
    }

    public static func get_hostname(ip_address: String): Option<String> {
        // Using low-level POSIX function to get hostname by IP
        let result = gethostbyaddr(ip_address)
        if result != null {
            return Some(result)
        } else {
            return None
        }
    }
}

