import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        let regex = Regex(#"[^a-zA-Z\s]"#)
        for (str in string_list) {
            let processed = regex.replaceAll(str.toLowerCase(), "", 0)
            let words = ArrayList<String>(processed.split())
            words_list.add(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let frequency_map = HashMap<String, Int64>()
        for (words in words_list) {
            for (word in words) {
                if (frequency_map.containsKey(word)) {
                    frequency_map.put(word, frequency_map.get(word) + 1)
                } else {
                    frequency_map.put(word, 1)
                }
            }
        }

        let entries = ArrayList<(String, Int64)>()
        for (key in frequency_map.keys()) {
            entries.add((key, frequency_map.get(key)))
        }

        sort(entries) { (a, b) -> Bool in a.1 > b.1 }

        let top_5 = HashMap<String, Int64>()
        let limit = entries.size() < 5 ? entries.size() : 5
        for (i in 0..limit) {
            top_5.put(entries.get(i).0, entries.get(i).1)
        }

        return top_5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

