        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if x.isNone() {
            return ""
        }
        return this.format_string(x.get())
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let parts = x.split('.')
        let lstr = parts[0]
        let rstr = parts.size() > 1 ? parts[1] : ""

        let lstrrev = lstr.reversed()
        var a: Array<String> = []

        var paddedLstrrev = lstrrev
        if lstrrev.size() % 3 == 1 {
            paddedLstrrev = lstrrev + "00"
        } else if lstrrev.size() % 3 == 2 {
            paddedLstrrev = lstrrev + "0"
        }

        let groupCount = paddedLstrrev.size() / 3
        var lm = ""
        for i in 0..<groupCount {
            let start = 3 * i
            let end = start + 3
            let segment = paddedLstrrev[start..<end].reversed()
            a.push(segment)
            if segment != "000" {
                lm = this.trans_three(segment) + " " + this.parse_more(i as Int64) + " " + lm
            } else {
                lm = this.trans_three(segment) + " " + lm
            }
        }

        let xs = !rstr.isEmpty() ? "AND CENTS " + this.trans_two(rstr.padEnd(2, '0')) + " " : ""
        if lm.trim().isEmpty() {
            return "ZERO ONLY"
        } else {
            return lm.trim() + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let padded = s.padStart(2, '0')
        let first = padded[0]
        let second = padded[1]
        let num = s.toInt()

        if first == '0' {
            return this.NUMBER[second.toInt() - '0'.toInt()]
        } else if first == '1' {
            return this.NUMBER_TEEN[num - 10]
        } else if second == '0' {
            return this.NUMBER_TEN[first.toInt() - '1'.toInt()]
        } else {
            return this.NUMBER_TEN[first.toInt() - '1'.toInt()] + " " + this.NUMBER[second.toInt() - '0'.toInt()]
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let first = s[0]
        let rest = s[1..<3]

        if first == '0' {
            return this.trans_two(rest)
        } else if rest == "00" {
            return this.NUMBER[first.toInt() - '0'.toInt()] + " HUNDRED"
        } else {
            return this.NUMBER[first.toInt() - '0'.toInt()] + " HUNDRED AND " + this.trans_two(rest)
        }
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        return this.NUMBER_MORE[i.toInt()]
    }
}
