import std.collection.ArrayList
import std.convert.RadixConvertible
import std.unicode.*

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        var out: ArrayList<Rune> = ArrayList<Rune>()
        var pos: Int64 = 0
        var length: Int64 = string.size()

        while pos < length - 2 {
            let char1: Rune = string.getUnchecked(pos)
            let char2: Rune = string.getUnchecked(pos + 1)

            if char1 == r'&' && char2 == r'#' {
                var start: Int64 = pos + 2
                var is_hex: Bool = false
                let first_char: Rune = string.getUnchecked(start)

                if first_char == r'x' || first_char == r'X' {
                    start = start + 1
                    is_hex = true
                }

                if start == length {
                    break
                }

                var end: Int64 = start
                while end < length && NumericEntityUnescaper.is_hex_char(string.getUnchecked(end)) {
                    end = end + 1
                }

                if end < length && string.getUnchecked(end) == r';' {
                    let substr: String = string.substringUnchecked(start, end)
                    var entity_value: Int64 = 0
                    if is_hex {
                        entity_value = Int64.parseHex(substr).getOrElse(0)
                    } else {
                        entity_value = Int64.parseDec(substr).getOrElse(0)
                    }

                    let rune: Rune = Rune.fromInt(entity_value).getOrElse(r'\u{FFFD}')
                    out.add(rune)
                    pos = end + 1
                    continue
                }
            }

            out.add(string.getUnchecked(pos))
            pos = pos + 1
        }

        while pos < length {
            out.add(string.getUnchecked(pos))
            pos = pos + 1
        }

        return out.joinToString("")
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.isAsciiHex()
    }
}

