        let fieldStr = fields match {
            case Some(f) => {
                var s = ""
                for (i in 0 ..< f.size()) {
                    if (i > 0) {
                        s += ", "
                    }
                    s += f[i]
                }
                s
            }
            case None => "*"
        }
        var sql = "SELECT ${fieldStr} FROM ${this.table_name}"
        condition match {
