import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = data.clone()
        sort(sorted_data)
        let n = sorted_data.size()
        if n % 2 == 1 {
            return Float64(sorted_data.at(n // 2))
        } else {
            let mid1 = Float64(sorted_data.at(n // 2 - 1))
            let mid2 = Float64(sorted_data.at(n // 2))
            return (mid1 + mid2) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for value in data {
            let count = counts.get(value) ?? 0
            counts.put(value, count + 1)
        }
        let max_count = counts.values().max() ?? 0
        let mode_values = ArrayList<Int64>()
        for (key, value) in counts {
            if value == max_count {
                mode_values.add(key)
            }
        }
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size()
        if n != y.size() || n == 0 {
            return None
        }
        let mean_x = (x.sum() as Float64) / Float64(n)
        let mean_y = (y.sum() as Float64) / Float64(n)
        var numerator: Float64 = 0.0
        var denominator_x: Float64 = 0.0
        var denominator_y: Float64 = 0.0
        for i in 0..<n {
            let xi = Float64(x.at(i))
            let yi = Float64(y.at(i))
            numerator += (xi - mean_x) * (yi - mean_y)
            denominator_x += (xi - mean_x) * (xi - mean_x)
            denominator_y += (yi - mean_y) * (yi - mean_y)
        }
        let denominator = sqrt(denominator_x * denominator_y)
        if denominator == 0.0 {
            return None
        }
        return Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.size() == 0 {
            return None
        }
        return Some((data.sum() as Float64) / Float64(data.size()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let matrix = ArrayList<ArrayList<Float64>>()
        let n = data.size()
        if n == 0 {
            return matrix
        }
        let m = data.at(0).size()
        for i in 0..<m {
            let row = ArrayList<Float64>()
            for j in 0..<m {
                let column1 = ArrayList<Int64>()
                let column2 = ArrayList<Int64>()
                for k in 0..<n {
                    column1.add(data.at(k).at(i))
                    column2.add(data.at(k).at(j))
                }
                let corr = correlation(column1, column2)
                row.add(corr ?? 0.0)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if n < 2 {
            return None
        }
        let mean_value = mean(data) ?? 0.0
        var variance: Float64 = 0.0
        for value in data {
            let diff = Float64(value) - mean_value
            variance += diff * diff
        }
        variance /= Float64(n - 1)
        return Some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_val = mean(data)
        let std_dev = standard_deviation(data)
        if mean_val.isNone() || std_dev.isNone() || std_dev.unwrap() == 0.0 {
            return None
        }
        let mean_unwrapped = mean_val.unwrap()
        let std_unwrapped = std_dev.unwrap()
        let result = ArrayList<Float64>()
        for value in data {
            result.add((Float64(value) - mean_unwrapped) / std_unwrapped)
        }
        return Some(result)
    }
}

