import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        return round(this.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        var b = Decimal(1)
        var a = a
        while a != 1 {
            b = b * Decimal(a)
            a = a - 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a: Float64 = 1.0
        x = x / 180.0 * this.PI
        var count = 1
        for k in 1..n {
            if count % 2 != 0 {
                a = a - (x ** (2 * k)) / this.factorial(2 * k).toFloat64()
            } else {
                a = a + (x ** (2 * k)) / this.factorial(2 * k).toFloat64()
            }
            count = count + 1
        }
        return a
    }

    public func sin(x: Float64): Float64 {
        x = x / 180.0 * this.PI
        var g: Float64 = 0.0
        var t = x
        var n: Int64 = 1

        while abs(t) >= 1e-15 {
            g = g + t
            n = n + 1
            t = -t * x * x / (2 * n - 1) / (2 * n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let cosValue = this.cos(x)
        if abs(cosValue - 0.0) > 0.000001 {
            let result = this.sin(x) / cosValue
            return Option.some(round(result, 10))
        } else {
            return Option.none()
        }
    }
}

