        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        if (path == null || path.isEmpty()) {
            return ""
        }

        var start = 0
        var end = path.length()

        if (path.charAt(0) == '/') {
            start = 1
        }

        if (path.charAt(end - 1) == '/') {
            end = end - 1
        }

        if (start >= end) {
            return ""
        }

        return path.substring(start, end)
    }
