        if this.orders.contains(key: order_id) {
            this.orders[order_id]!.status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        if this.orders.contains(key: order_id) {
            return Some(this.orders[order_id]!.status)
        } else {
            return None()
        }
